async function addToCart(n,t){const i=t.textContent;t.disabled=!0;t.innerHTML='<span class="spinner-border spinner-border-sm me-1"><\/span>Добавление...';try{const r=await fetch("/Catalog/AddToCart",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded",Accept:"application/json"},body:"id="+encodeURIComponent(n)});if(!r.ok)throw new Error("HTTP "+r.status);const u=await r.json();if(!u.success){alert("Ошибка: "+(u.message||"неизвестная"));resetButton(t,i);return}const f=document.getElementById("cartBadge");f&&(f.textContent=u.cartCount);t.innerHTML="Добавлено ✓";t.classList.remove("btn-primary");t.classList.add("btn-success");setTimeout(function(){resetButton(t,i)},2e3)}catch(r){console.error(r);t.textContent="Ошибка";t.disabled=!1;setTimeout(function(){resetButton(t,i)},2e3)}}function resetButton(n,t){n.textContent=t;n.classList.remove("btn-success");n.classList.add("btn-primary");n.disabled=!1}document.addEventListener("click",function(n){const t=n.target.closest(".add-to-cart");if(t&&!t.disabled){const i=t.dataset.productId;i&&(n.preventDefault(),addToCart(i,t))}});